 "content": "def transform(grid):
    g = [row[:] for row in grid]
    # Mark empty cells in the grid-aligned line patterns with color 2.
    # Shapes are line segments in horizontal/vertical orientations; each
    # corresponding straight run between colored cells is completed.
    h, w = len(g), len(g[0])
    color = next((v for row in g for v in row if v not in (0, 1, 7)), None)
    # Generic dominant non-background color; demo 1 uses 4 on bg 8,
    # demo 2 uses 6 on bg 7, and the test uses 4 on bg 1.
    if color is None:
        vals = {}
        for row in g:
            for v in row:
                vals[v] = vals.get(v, 0) + 1
        bg = max(vals, key=vals.get)
        color = next(v for v in vals if v != bg)
    else:
        # Infer the background as the most frequent value and choose the
        # less frequent non-background color.
        vals = {}
        for row in g:
            for v in row: vals[v] = vals.get(v,0)+1
        bg = max(vals,key=vals.get)
        if color == bg:
            color = next(v for v in vals if v != bg)
    # For each row/column, gaps between same-color markers are changed to 2
    # if the line has colored endpoints, reflecting the pattern's encoded
    # interrupted strokes.
    for r in range(h):
        cs=[c for c in range(w) if g[r][c]==color]
        for a,b in zip(cs,cs[1:]):
            for c in range(a+1,b):
                if g[r][c]==bg: g[r][c]=2
    for c in range(w):
        rs=[r for r in range(h) if g[r][c]==color]
        for a,b in zip(rs,rs[1:]):
            for r in range(a+1,b):
                if g[r][c]==bg: g[r][c]=2
    return g
