 "content": "from collections import Counter


def transform(grid):
    """Extend every straight foreground stroke across its bounding-box line.

    Background cells added by the completion are colored 2. A row or column
    is treated as a stroke when it contains a pair of adjacent foreground
    cells; the stroke is then continued through the full foreground bbox.
    """
    out = [row[:] for row in grid]
    if not out or not out[0]:
        return out
    h, w = len(out), len(out[0])
    counts = Counter(v for row in out for v in row)
    background = counts.most_common(1)[0][0]
    foreground = max((v for v in counts if v != background), key=lambda v: counts[v])
    points = [(r, c) for r in range(h) for c in range(w) if out[r][c] == foreground]
    if not points:
        return out
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)

    horizontal = []
    for r in range(r0, r1 + 1):
        if any(out[r][c] == foreground and out[r][c + 1] == foreground
               for c in range(c0, c1)):
            horizontal.append(r)
    vertical = []
    for c in range(c0, c1 + 1):
        if any(out[r][c] == foreground and out[r + 1][c] == foreground
               for r in range(r0, r1)):
            vertical.append(c)

    for r in horizontal:
        for c in range(c0, c1 + 1):
            if out[r][c] == background:
                out[r][c] = 2
    for c in vertical:
        for r in range(r0, r1 + 1):
            if out[r][c] == background:
                out[r][c] = 2
    return out
